(function(){'use strict';
const E=window.CastawayCampaign,S=window.CastawayStory,$=id=>document.getElementById(id),KEY='castaways-campaign-v2',PREF='castaways-preferences-v2';
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const labels={food:'Zásoby',hope:'Naděje',craft:'Zkušenost',trust:'Důvěra'},roman=['I','II','III','IV','V','VI','VII','VIII','IX','X','XI','XII'];
let state=E.createGame(),saving=true,lastScene='',walkTimer,audioContext=null,audioGain=null,sound=false;
let reduced=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
try{const raw=JSON.parse(localStorage.getItem(KEY));state=E.restoreGame(raw,S)||state;const pref=JSON.parse(localStorage.getItem(PREF));if(pref&&typeof pref.reduced==='boolean')reduced=reduced||pref.reduced;}catch(_){}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));saving=true;}catch(_){saving=false;}}
function modal(eyebrow,title,html){$('modal-eyebrow').textContent=eyebrow;$('modal-title').textContent=title;$('modal-body').innerHTML=html;if(!$('modal').open)$('modal').showModal();}
function paragraphs(value){return (Array.isArray(value)?value:[value]).map(p=>`<p>${esc(p)}</p>`).join('');}
function effectTags(effects,preview=false){return `<div class="effects">${Object.entries(effects).filter(([k,n])=>n).map(([k,n])=>{const actual=preview?Math.max(0,Math.min(10,state.stats[k]+n))-state.stats[k]:n;return `<span class="effect ${actual<0?'negative':''}">${labels[k]} ${actual>0?'+':''}${actual}${preview&&actual!==n?' · mez škály':''}</span>`;}).join('')}</div>`;}
const primary=(label,id='continue')=>`<button class="primary" id="${id}">${esc(label)} <span class="arrow" aria-hidden="true">→</span></button>`;
function setMotion(){document.body.classList.toggle('reduced-motion',reduced);$('motion-button').setAttribute('aria-pressed',String(reduced));$('motion-button').setAttribute('aria-label',reduced?'Zapnout animace':'Omezit animace');$('motion-button').innerHTML=`${reduced?'○':'≈'} <span>${reduced?'Klidný obraz':'Pohyb'}</span>`;try{localStorage.setItem(PREF,JSON.stringify({reduced}));}catch(_){}}
function moveTraveller(x,y){$('traveller').style.left=Math.max(12,Math.min(92,x))+'%';$('traveller').style.top=Math.max(180,Math.min(window.innerHeight*.52,y))+'px';$('traveller').classList.add('walking');clearTimeout(walkTimer);walkTimer=setTimeout(()=>$('traveller').classList.remove('walking'),1900);}
function updateScene(chapter){$('world').dataset.scene=chapter.scene;$('world').dataset.weather=chapter.weather;const signature=chapter.scene+chapter.weather;if(signature!==lastScene){lastScene=signature;$('painting').animate([{opacity:.3},{opacity:1}],{duration:reduced?0:1200});} $('scene-date').textContent=chapter.date;$('scene-title').textContent=state.phase==='ending'?'Dokud se nevrátíme':chapter.title;$('scene-location').textContent=chapter.location;}
function render(focus=false){
 const {chapter,step}=E.current(state,S),p=E.progress(state,S);updateScene(chapter);
 $('chapter-counter').textContent=`KAPITOLA ${roman[state.chapter]} / XII`;$('chapter-place').textContent=chapter.location;$('progress-label').textContent=`${p.completed} / ${p.total} rozhodnutí`;$('progress-fill').style.width=p.percent+'%';$('journal-count').textContent=state.choices.length;
 $('undo-button').disabled=!state.history.length;$('save-state').textContent=saving?'Průběh uložen v tomto prohlížeči':'Úložiště nedostupné · ponech hru otevřenou';
 $('stats').innerHTML=Object.entries(labels).map(([key,label])=>`<div><div class="stat-heading"><span>${label}</span><b>${state.stats[key]} / 10</b></div><div class="stat-track" role="meter" aria-label="${label}" aria-valuemin="0" aria-valuemax="10" aria-valuenow="${state.stats[key]}">${Array.from({length:10},(_,i)=>`<i class="${i<state.stats[key]?'filled':''}"></i>`).join('')}</div></div>`).join('');
 const stepNumber=state.step+1;let html='';
 if(state.phase==='intro')html=`<div class="eyebrow">KAPITOLA ${roman[state.chapter]} · ${state.chapter===0?'ZAČÁTEK CESTY':'DALŠÍ LIST PŘÍBĚHU'}</div><h2>${esc(chapter.title)}</h2>${paragraphs(chapter.intro)}<p class="objective">${esc(chapter.objective)}</p><div class="story-actions">${primary(state.chapter===0?'Začít příběh':'Vstoupit do kapitoly')}<button class="text-link" id="how-to">Jak se hraje</button></div>`;
 if(state.phase==='decision')html=`<div class="eyebrow">ROZHODNUTÍ ${stepNumber} ZE ${chapter.steps.length}</div><h2>${esc(step.title)}</h2>${paragraphs(step.narration)}${step.dialogue?`<div class="dialogue"><span class="speaker">${esc(step.speaker)}</span><p>${esc(step.dialogue)}</p></div>`:''}<div class="choice-list">${step.choices.map((c,i)=>`<button class="choice" data-choice="${esc(c.id)}"><span class="choice-index" aria-hidden="true">${roman[i]}</span><span><strong>${esc(c.label)}</strong><small>${esc(c.detail)}</small>${effectTags(c.effects,true)}</span></button>`).join('')}</div>`;
 if(state.phase==='result')html=`<div class="eyebrow">VAŠE ROZHODNUTÍ · ${stepNumber} / ${chapter.steps.length}</div><h2>${esc(state.result.label)}</h2>${paragraphs(state.result.log)}<div class="result-summary"><span class="eyebrow">CO SI NESETE DÁL</span>${effectTags(state.result.actualEffects)}<p>${esc(state.result.reflection)}</p></div><div class="story-actions">${primary(stepNumber<chapter.steps.length?'Pokračovat příběhem':'Uzavřít kapitolu')}<button class="text-link" id="result-undo">Promyslet volbu znovu</button></div>`;
 if(state.phase==='chapter_end')html=`<div class="eyebrow">ZÁVĚR KAPITOLY ${roman[state.chapter]}</div><h2>${esc(chapter.title)}</h2><p class="chapter-ending">${esc(chapter.closing)}</p><div class="story-actions">${primary(chapter.archive?'Pohled z druhého břehu':state.chapter===S.chapters.length-1?'Dočíst epilog':'Otevřít další kapitolu')}<button class="text-link" id="chapter-source">Historická poznámka</button></div>`;
 if(state.phase==='archive')html=`<div class="archive-mark">ARCHIVNÍ MEZIHRA · INVERCAULD</div><h2>${esc(chapter.archive.title)}</h2>${paragraphs(chapter.archive.text)}<p class="small-note">Tuto perspektivu trosečníci Graftonu během pobytu neznali. Nejde o jejich setkání.</p><div class="story-actions">${primary('Zpět k příběhu Graftonu')}<button class="text-link" id="archive-source">Pramen svědectví ↗</button></div>`;
 if(state.phase==='ending'){const end=E.ending(state);html=`<div class="eyebrow">EPILOG · VŠICHNI PĚT</div><div class="ending-five">5 <span style="font-size:20px">z pěti</span></div><h2>${esc(end.subtitle)}</h2>${paragraphs([end.text,end.reflection,end.preparation])}<div class="ending-metrics">${Object.entries(labels).map(([k,l])=>`<div><span>${l}</span><b>${state.stats[k]} / 10</b></div>`).join('')}</div><p class="small-note">Došli jste celým příběhem: ${end.decisions} rozhodnutí, 12 kapitol a tři archivní pohledy. Konec patří návratu pro druhé, nejen vlastní záchraně.</p><div class="story-actions">${primary('Prolistovat naši cestu','ending-journal')}<button class="text-link" id="ending-new">Začít jinou cestu</button><a class="text-link" href="legacy/index.html">Původní strategická studie ↗</a></div>`;}
 $('story-content').innerHTML=html;$('story-content').classList.remove('fade-enter');void $('story-content').offsetWidth;$('story-content').classList.add('fade-enter');
 const go=$('continue');if(go)go.onclick=()=>{state=E.advance(state,S);save();render(true);};
 $('story-content').querySelectorAll('[data-choice]').forEach(button=>button.onclick=()=>{state=E.choose(state,button.dataset.choice,S);moveTraveller(58+state.step*13,window.innerHeight*.37);save();render(true);});
 const bind=(id,fn)=>{if($(id))$(id).onclick=fn;};bind('result-undo',undo);bind('how-to',help);bind('chapter-source',sources);bind('archive-source',()=>showSource(chapter.archive.source));bind('ending-journal',journal);bind('ending-new',restart);
 $('hotspots').innerHTML=state.phase==='decision'?`<button class="hotspot" style="left:${window.innerWidth<700?75:72+state.step*5}%;top:65%" data-label="${esc(step.title)}" aria-label="Přejít k rozhodnutí: ${esc(step.title)}">${roman[state.step]}</button>`:'';
 const hot=$('hotspots').querySelector('button');if(hot)hot.onclick=event=>{event.stopPropagation();moveTraveller(76,window.innerHeight*.38);$('reading').scrollIntoView({behavior:reduced?'instant':'smooth',block:'start'});$('reading').focus({preventScroll:true});};
 $('stage-hint').textContent=state.phase==='decision'?'Zářící místo tě zavede k rozhodnutí.':'Krajina se hýbe. Příběh čeká na tebe.';
 if(focus){$('reading').focus({preventScroll:true});const r=$('reading').getBoundingClientRect();if(r.top<80||r.top>window.innerHeight*.65)$('reading').scrollIntoView({behavior:reduced?'instant':'smooth',block:'start'});}
}
function undo(){if(!state.history.length)return;state=E.undo(state);save();render(true);}
function help(){modal('PRŮVODCE','Cesta, kterou projdeš vlastním tempem',`<p>Každá z dvanácti kapitol má tři rozhodnutí. Přečti si situaci, vyber možnost a prohlédni její následek. Tlačítko se šipkou tě vždy vede dál.</p><p>Zásoby, naděje, zkušenost a důvěra ovlivňují komentář a závěrečné ohlédnutí. Žádná hodnota nezablokuje příběh. Čísla u voleb ukazují skutečnou změnu po započtení mezí škály.</p><p>Kliknutí do krajiny rozpohybuje postavu; zářící bod tě zavede k aktuálnímu rozhodnutí. Ve spodní liště můžeš vrátit dřívější volby. Kapitoly a Deník ti připomenou cestu.</p><p class="small-note">Hra se ukládá pouze v tomto prohlížeči. Rozhraní lze ovládat klávesami Tab a Enter. Pohyb lze omezit, zvuk je ve výchozím stavu vypnutý.</p>`);}
function showSource(source){if(!source)return;modal('FAKTA A AUTORSKÁ REKONSTRUKCE',source.label,`${paragraphs(source.detail)}<p><a href="${esc(source.url)}" target="_blank" rel="noopener noreferrer">Otevřít pramenný podklad ↗</a></p><p>Všechny rozhovory, rozhodnutí, ukazatele a malby jsou vytvořené pro tuto hru. Historická data a opora v pramenech jsou vedeny odděleně. Obrazy neznázorňují přesný archeologický stav místa.</p><p class="small-note">Posádky Graftonu a Invercauldu se během trosečnického pobytu nesetkaly. Archivní mezihry nespojují jejich tábory ani nepřipisují nejistý kouř konkrétním lidem.</p>`);}
function sources(){showSource(E.current(state,S).chapter.source);}
function map(){modal('OBSAH · 1864—1865','Dvanáct kapitol návratu',`<p class="small-note">Dokončené kapitoly můžeš znovu číst. Pozdější se otevřou postupem příběhu.</p><div class="chapter-list">${S.chapters.map((c,i)=>`<button class="chapter-item ${i===state.chapter?'current':''}" data-chapter="${i}" ${i>state.chapter?'disabled':''}><span>${roman[i]}</span><div><strong>${esc(c.title)}</strong><small>${esc(c.date)}</small></div><em>${i<state.chapter||state.phase==='ending'?'Dočteno':i===state.chapter?'Právě zde':'Později'}</em></button>`).join('')}</div>`);$('modal-body').querySelectorAll('[data-chapter]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.chapter),c=S.chapters[i];if(i===state.chapter&&state.phase!=='ending'){$('modal').close();$('reading').scrollIntoView({behavior:'smooth'});return;}modal(`KAPITOLA ${roman[i]} · OHLÉDNUTÍ`,c.title,`${paragraphs(c.intro)}<p class="chapter-ending">${esc(c.closing)}</p>${state.journal.filter(x=>x.chapter===i&&x.kind==='decision').map(x=>`<article class="journal-entry"><h3>${esc(x.title.split(' · ').at(-1))}</h3><p>${esc(x.text)}</p></article>`).join('')}<div class="story-actions"><button class="primary" id="back-map">Zpět na kapitoly</button></div>`);$('back-map').onclick=map;});}
function journal(){modal('DENÍK VAŠÍ CESTY',state.choices.length?'Co jsme rozhodli':'První stránka zatím čeká',state.journal.length?state.journal.slice().reverse().map(x=>`<article class="journal-entry"><div class="eyebrow">${x.kind==='archive'?'ARCHIV · CIZÍ SVĚDECTVÍ':`KAPITOLA ${roman[x.chapter]}`}</div><h3>${esc(x.title)}</h3>${paragraphs(String(x.text).split('\n\n'))}</article>`).join(''):'<p>První zápis vznikne po vstupu do kapitoly. Každá další volba tu zanechá stopu.</p>');}
function toggleSound(){try{if(!audioContext){const AC=window.AudioContext||window.webkitAudioContext;if(!AC)throw Error();audioContext=new AC();const buffer=audioContext.createBuffer(1,audioContext.sampleRate*3,audioContext.sampleRate),data=buffer.getChannelData(0);let last=0;for(let i=0;i<data.length;i++){last=(last+.02*(Math.random()*2-1))/1.02;data[i]=last*3.5;}const noise=audioContext.createBufferSource();noise.buffer=buffer;noise.loop=true;const filter=audioContext.createBiquadFilter();filter.type='lowpass';filter.frequency.value=550;audioGain=audioContext.createGain();audioGain.gain.value=0;noise.connect(filter);filter.connect(audioGain);audioGain.connect(audioContext.destination);noise.start();}sound=!sound;audioContext.resume().catch(()=>{});audioGain.gain.setTargetAtTime(sound?.3:0,audioContext.currentTime,.5);settings();}catch(_){modal('ZVUK','Zvuk není dostupný','<p>V tomto prohlížeči se zvuk nepodařilo spustit. Příběh můžeš celý dohrát bez něj.</p>');}}
function settings(){modal('PŘIZPŮSOBENÍ','Vlastním tempem',`<div class="setting"><span>Pohyb krajiny a počasí</span><button id="setting-motion">${reduced?'Omezený':'Zapnutý'}</button></div><div class="setting"><span>Tichý zvuk větru a moře</span><button id="setting-sound">${sound?'Vypnout':'Zapnout'}</button></div><div class="setting"><span>Ovládání a smysl ukazatelů</span><button id="setting-help">Jak hrát</button></div><div class="setting"><span>Rozehraný příběh</span><button id="setting-restart">Nová cesta</button></div><p class="small-note">Pohyb také respektuje nastavení operačního systému. Zvuk se spouští pouze na tvé přání. Žádné herní volby se neodesílají na server.</p><p class="small-note">Malby jsou původní výtvarné rekonstrukce vytvořené pomocí AI. Dialogy jsou autorská fikce, nikoli citace historických osob.</p><a class="text-link" href="legacy/index.html">Otevřít původní strategickou studii</a>`);$('setting-motion').onclick=()=>{reduced=!reduced;setMotion();settings();};$('setting-sound').onclick=toggleSound;$('setting-help').onclick=help;$('setting-restart').onclick=restart;}
function restart(){modal('NOVÁ CESTA','Otevřít první stránku znovu?',`<p>Tím nahradíš uložený postup této kampaně. Původní strategická studie má vlastní ukládání.</p><div class="story-actions">${primary('Začít znovu','restart-confirm')}<button class="text-link" id="restart-cancel">Zůstat v příběhu</button></div>`);$('restart-cancel').onclick=()=>$('modal').close();$('restart-confirm').onclick=()=>{state=E.createGame();$('modal').close();save();render(true);window.scrollTo({top:0,behavior:reduced?'instant':'smooth'});};}
$('brand').onclick=e=>{e.preventDefault();map();};$('map-button').onclick=map;$('journal-button').onclick=journal;$('source-button').onclick=sources;$('settings-button').onclick=settings;$('undo-button').onclick=undo;$('motion-button').onclick=()=>{reduced=!reduced;setMotion();};$('modal-close').onclick=()=>$('modal').close();
$('modal').addEventListener('click',e=>{if(e.target===$('modal')){const r=$('modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('modal').close();}});
$('stage').onclick=e=>{if(e.target.closest('button'))return;moveTraveller(e.clientX/window.innerWidth*100,e.clientY);};
let pending=false;document.addEventListener('pointermove',e=>{if(reduced||pending||e.pointerType==='touch')return;pending=true;requestAnimationFrame(()=>{document.documentElement.style.setProperty('--px',(e.clientX/window.innerWidth-.5).toFixed(2));document.documentElement.style.setProperty('--py',(e.clientY/window.innerHeight-.5).toFixed(2));pending=false;});});
document.addEventListener('visibilitychange',()=>{if(audioGain)audioGain.gain.setTargetAtTime(sound&&!document.hidden?.3:0,audioContext.currentTime,.2);});
$('rain').innerHTML=Array.from({length:36},(_,i)=>`<i style="--x:${(i*37)%105}%;--speed:${.6+(i%7)*.09}s;--delay:-${i*.14}s"></i>`).join('');$('snow').innerHTML=Array.from({length:25},(_,i)=>`<i style="--x:${(i*31)%100}%;--speed:${5+i%8}s;--delay:-${i*.7}s"></i>`).join('');
setMotion();save();render();
})();
